package main

import (
	"fmt"
	"reflect"
)

type User struct {
	Name string `json:"name"`
	Age  int    `json:"age,omitempty"`
}

func main() {
	u := User{Name: "Ada", Age: 36}
	t := reflect.TypeOf(u)  // main.User
	v := reflect.ValueOf(u) // the data
	fmt.Println("type:", t, "kind:", t.Kind())
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)                 // field metadata
		tag := f.Tag.Get("json")        // read the json struct tag
		fmt.Printf("%s = %v (json:%q)\n", f.Name, v.Field(i), tag)
	}
}

