package main

import (
	"fmt"
	"reflect"
)

func main() {
	x := 7
	v := reflect.ValueOf(&x).Elem() // pointer -> Elem() is addressable & settable
	if v.CanSet() {                 // good practice: guard before Set
		v.SetInt(99)
	}
	fmt.Println(x) // 99
}

